export const aaSeptember8Observations: MetricObservation[] = [
  ...runs.flatMap(run => Object.entries(run.scores).map(([metricId, value]): MetricObservation => ({
    modelId: run.modelId,
    metricId,
    value,
    observationDate: '2026-09-08',
    sourceUrl: metricId === 'automationbench'
      ? 'https://artificialanalysis.ai/evaluations/automationbench-aa'
      : `https://artificialanalysis.ai/models/${run.slug}`,
    reasoningBudget: run.effort ?? 'Not published',
    reasoningMode: 'reasoning',
    scaffoldOrHarness: harnesses[metricId] ?? 'AA-Omniscience; 6,000 questions; independent evaluation',
    notes: [
      `AA v4.3 publication snapshot; model configuration: https://artificialanalysis.ai/models/${run.slug}.`,
      run.effort === null ? 'Effort not published; Top-only assumption, not an established native setting.' : '',
      run.modelId === 'claude-fable-5-1-max' ? 'Published Default Fallback configuration; not a standalone Fable-only run.' : '',
      run.modelId === 'deepseek-v4-pro-max' ? 'DeepSeek V4 Pro 0813 release.' : '',
      run.modelId === 'deepseek-v4-flash-0731' ? 'DeepSeek V4 Flash 0731 release.' : '',
      run.modelId === 'qwen3-8-max' ? 'Original August 3 Qwen3.8 Max release; not Max 0902 or open weights.' : '',
      metricId === 'gdp-pdf' ? 'AA All-pass: fraction of 500 attempts passing every atomic criterion. Text-only models receive document text; native vision is not required. AA and Surge harness results remain separate.' : '',
      metricId === 'automationbench-aa' ? 'AA headline Score: mean task objective completion, zero for any guardrail violation. Distinct from the strict automationbench fallback.' : '',
      metricId === 'automationbench' ? 'AA strictScore: every objective met and no guardrail violations. Same v1.0.6 held-out strict task definition as the existing fallback; AA harness retained. Partial-objective Score is not imported.' : ''
