import type { CrossEffortCalibration, FallbackCalibration, LeafContribution, MetricDefinition, MetricObservation, ModelRelease, RawMetricDefinition } from '../types';
import { metricSignature, predictCalibration } from './calibration';
import { normalizeRawValue } from './normalizer';
import { readFallbackSource, requiresVision } from './fallbackSources';

export function resolveBenchmark(
  model: ModelRelease, target: RawMetricDefinition, effectiveWeight: number,
  metrics: Map<string, MetricDefinition>, observations: Map<string, MetricObservation>,
  calibrations: FallbackCalibration[], crossEffort?: CrossEffortCalibration
): LeafContribution {
  const primary = observations.get(`${model.id}:${target.id}`);
  const result: LeafContribution = {
    rawMetric: target, rawValue: primary?.value ?? null, state: 'missing', hasEvidence: false,
    normalizedValue: 0, effectiveWeight, pointsContributed: 0, explanation: 'No usable result.'
  };
  if (target.requiresVisionInput && model.visionInput === 'unsupported') {
    if (primary) return { ...result, explanation: 'Vision metadata conflicts with a recorded image evaluation; review required.' };
    return { ...result, state: 'unsupported', hasEvidence: true, explanation: 'Cannot accept required image input; assigned zero points.' };
  }
  if (primary) {
    const normalizedValue = normalizeRawValue(primary.value, target);
    return { ...result, state: 'measured', hasEvidence: true, sourceObservation: primary, sourceMetric: target,
      normalizedValue, pointsContributed: normalizedValue * effectiveWeight, explanation: 'Preferred benchmark measurement.' };
  }
  const pendingSources: string[] = [];
  for (const sourceId of target.fallbackMetricIds ?? []) {
    const source = metrics.get(sourceId);
    if (!source || (target.requiresVisionInput && !requiresVision(source, metrics))) continue;
    const evidence = readFallbackSource(model, source, metrics, observations,
      ['quality', 'knowledge', 'vision'].includes(target.family) ? crossEffort : undefined);
    if (!evidence) continue;
    const calibration = calibrations.find(route => route.targetMetricId === target.id && route.sourceMetricId === sourceId
      && route.targetSignature === metricSignature(target) && route.sourceSignature === metricSignature(source, metrics));
    if (calibration?.status !== 'ready' || !calibration.scale) {
      pendingSources.push(source.name);
      continue;
    }
    const modelCalibration = calibration.modelScales?.find(pair =>
      pair.releaseId === (model.reasoningConfiguration?.releaseId ?? model.id)
      && pair.reasoningMode === (model.isReasoningModel ? 'reasoning' : 'non-reasoning'));
    const scaled = modelCalibration?.scale ?? calibration.scale;
    const normalizedValue = predictCalibration(scaled, evidence.score);
    const usesCrossEffort = evidence.components.some(part => part.state === 'cross-effort');
    return { ...result, state: 'estimated', hasEvidence: true, sourceMetric: source,
      sourceObservation: source.kind === 'raw' ? evidence.components[0]?.observation : undefined,
      sourceComponents: source.kind === 'composite' || evidence.components.some(part => part.state !== 'measured')
        ? evidence.components : undefined,
      normalizedValue, pointsContributed: normalizedValue * effectiveWeight,
      perfectVisionValue: predictCalibration(scaled, evidence.perfectVisionScore),
      calibrationId: calibration.id, modelCalibration, estimateKind: usesCrossEffort ? 'cross-effort' : 'scaled',
      crossEffort: usesCrossEffort ? crossEffort : undefined,
      explanation: `Scale-adjusted from ${source.name} using ${modelCalibration
        ? `this release's own measured conversion (${modelCalibration.effort ?? 'effort not published'}; factor ${(scaled.targetAnchor / scaled.sourceAnchor).toFixed(4)})`
        : calibration.method === 'manual' ? 'manual calibration' : `paired averages (${String(calibration.pairedCount)} models)`}.`
        + (usesCrossEffort && crossEffort ? ` Cross-effort estimate: missing source inputs use this release's real ${crossEffort.topEffort ?? 'unpublished-effort'} measurements × ${crossEffort.factor.toFixed(4)} before benchmark conversion.` : '')
        + (pendingSources.length ? ` Skipped ${pendingSources.join(', ')}: calibration required.` : '') };
  }
  return pendingSources.length ? { ...result, explanation: `Result recorded for ${pendingSources.join(', ')}; calibration required before it can contribute points or coverage.` } : result;
}

src/engine/calculator.ts:
import {
  CalculatedModelScore,
  FallbackCalibration,
  LeafContribution,
  MetricDefinition,
  MetricObservation,
  ModelRelease,
  RawMetricDefinition
} from '../types';
import { resolveEffectiveLeafWeights } from './dag';
import { fallbackCalibrations } from '../data/calibrations';
import { resolveBenchmark } from './benchmarkResolver';
import { calculateScoreUncertainty } from './uncertainty';
import { selectBestObservations } from './observations';
import { buildCrossEffortCalibrations, estimateCrossEffort } from './crossEffort';
import { estimatePerformance } from './performanceEstimates';

/**
 * Calculates synthetic index scores for all models against a root metric definition.
 * Measurements, calibrated estimates and confirmed unsupported vision resolve a component.
 * At least 95% evidence coverage qualifies for ranking; missing weight adds to uncertainty.
 * Weights are never redistributed.
 */
export function calculateIndexScores(
  rootMetricId: string,
  models: ModelRelease[],
  metricMap: Map<string, MetricDefinition>,
  observations: MetricObservation[],
  calibrations: FallbackCalibration[] = fallbackCalibrations,
  evidenceModels: ModelRelease[] = models
): CalculatedModelScore[] {
  // 1. Flatten root metric into effective leaf weights
  const effectiveLeaves = resolveEffectiveLeafWeights(rootMetricId, metricMap);

  const obsMap = selectBestObservations(evidenceModels, metricMap, observations);
  const crossEffort = buildCrossEffortCalibrations(evidenceModels, metricMap, obsMap);

  // 3. Score each model
  const modelScores: CalculatedModelScore[] = models.map((model) => {
    let totalScore = 0;
    let coveredWeight = 0;
    let estimatedWeight = 0;
    let crossEffortWeight = 0;
    let unsupportedWeight = 0;
    let perfectVisionGain = 0;
    let hasAllRequiredObservations = true;
    const leafBreakdown: LeafContribution[] = [];

    for (const leaf of effectiveLeaves) {
      const rawDef = metricMap.get(leaf.rawMetricId) as RawMetricDefinition;
      const estimated = estimateCrossEffort(
        resolveBenchmark(model, rawDef, leaf.effectiveWeight, metricMap, obsMap, calibrations),
        model, crossEffort.get(model.id), obsMap);
      const capability = estimated.state === 'missing' && crossEffort.has(model.id)
        ? resolveBenchmark(model, rawDef, leaf.effectiveWeight, metricMap, obsMap, calibrations, crossEffort.get(model.id))
        : estimated;
      const resolved = estimatePerformance(capability, model);
      totalScore += resolved.pointsContributed;
      const perfectVisionValue = resolved.state === 'unsupported' ? 100 : resolved.perfectVisionValue ?? resolved.normalizedValue;
      perfectVisionGain += (perfectVisionValue - resolved.normalizedValue) * leaf.effectiveWeight;
      if (resolved.state === 'measured') coveredWeight += leaf.effectiveWeight;
      if (resolved.state === 'estimated') estimatedWeight += leaf.effectiveWeight;
      if (resolved.estimateKind === 'cross-effort') crossEffortWeight += leaf.effectiveWeight;
      if (resolved.state === 'unsupported') unsupportedWeight += leaf.effectiveWeight;
      if (resolved.state === 'missing' && leaf.effectiveWeight > 0) hasAllRequiredObservations = false;
      leafBreakdown.push(resolved);
    }

    // Sort leaf breakdown by effective weight descending
    leafBreakdown.sort((a, b) => b.effectiveWeight - a.effectiveWeight);

    const evidencePercent = leafBreakdown.reduce((sum, leaf) =>
      sum + (leaf.hasEvidence ? leaf.effectiveWeight : 0), 0) * 100;
    // Account only for floating-point arithmetic at the inclusive 95% boundary, not display rounding.
    const isEligible = evidencePercent >= 95 - 1e-10;
    // Display rounding must not suggest an incomplete model is complete or an ineligible model meets 95%.
    const coveragePercent = hasAllRequiredObservations ? 100
      : Math.min(isEligible ? 99.9 : 94.9, Math.round(evidencePercent * 10) / 10);

    return {
      model,
      score: totalScore,
      rank: null, // Assigned strictly to eligible models below
      isEligible,
      coveragePercent,
      measuredPercent: coveredWeight * 100,
      estimatedPercent: estimatedWeight * 100,
      crossEffortEstimatedPercent: crossEffortWeight * 100,
      unsupportedPercent: unsupportedWeight * 100,
      perfectVisionScore: Math.min(100, totalScore + perfectVisionGain),
      uncertainty: calculateScoreUncertainty(leafBreakdown, isEligible),
      leafBreakdown
    };
  });

  // 4. Split into Eligible (Official) and Ineligible (Provisional) cohorts
  const eligibleModels = modelScores.filter((m) => m.isEligible);
  const provisionalModels = modelScores.filter((m) => !m.isEligible);

  const scoreComparator = (a: CalculatedModelScore, b: CalculatedModelScore) => {
    if (b.score !== a.score) {
      return b.score - a.score;
    }
    const topLeafA = a.leafBreakdown[0]?.pointsContributed ?? 0;
    const topLeafB = b.leafBreakdown[0]?.pointsContributed ?? 0;
    if (topLeafB !== topLeafA) {
      return topLeafB - topLeafA;
    }
    return a.model.name.localeCompare(b.model.name);
  };

  eligibleModels.sort(scoreComparator);
  provisionalModels.sort(scoreComparator);

  // 5. Assign official ranks ONLY to eligible models
  let currentRank = 1;
  for (let i = 0; i < eligibleModels.length; i++) {
    if (i > 0 && eligibleModels[i].score < eligibleModels[i - 1].score) {
      currentRank = i + 1;
    }
    eligibleModels[i].rank = currentRank;
  }

  // Provisional models keep rank = null
  for (const prov of provisionalModels) {
    prov.rank = null;
  }

  // Return official eligible models first, followed by provisional models
  return [...eligibleModels, ...provisionalModels];
}

