import data from '../data/performanceEstimates.json';
import type { LeafContribution, ModelRelease, PerformanceEstimate } from '../types';
import { normalizeRawValue } from './normalizer';

export const PERFORMANCE_ESTIMATE_POLICY = data.policy;
export const performanceEstimates = data.configurations as PerformanceEstimate[];
const byModel = new Map(performanceEstimates.map(estimate => [estimate.modelId, estimate]));

/** Frozen component fits remain independent of roster filtering and measurement selection. */
export function getPerformanceEstimate(model: ModelRelease): PerformanceEstimate | undefined {
  const estimate = byModel.get(model.id);
  const config = model.reasoningConfiguration;
  return model.isReasoningModel && config && ['middle', 'lowest'].includes(config.tier)
    && estimate?.releaseId === config.releaseId && estimate.effort === config.effort ? estimate : undefined;
}

/** Only unresolved performance values use this layer; estimates never become observations. */
export function estimatePerformance(leaf: LeafContribution, model: ModelRelease): LeafContribution {
  if (leaf.state !== 'missing') return leaf;
  const estimate = getPerformanceEstimate(model);
  const value = estimate?.values[leaf.rawMetric.id];
  if (!estimate || value === undefined) return leaf;
  const normalizedValue = normalizeRawValue(value, leaf.rawMetric);
  return { ...leaf, state: 'estimated', hasEvidence: true, estimateKind: 'performance',
    performanceEstimate: estimate, rawValue: value, normalizedValue,
    pointsContributed: normalizedValue * leaf.effectiveWeight,
    explanation: (estimate.notes ? `${estimate.notes} ` : '') + `Performance estimate from this release's reference components (${estimate.topEffort} → ${estimate.effort}). `
      + (estimate.route === 'hybrid' ? 'Peer component ratios blended with measured latency and speed changes.'
        : 'Peer component ratios with measured lower-effort speed when available; missing timing uses peer ratios.')
      + (estimate.topEffortAssumed ? ' Reference native effort was not published; the source applies only to the reference configuration.' : '') };
}

