import type { CalculatedModelScore } from '../types';

export function formatMargin(margin: number | null): string {
  return margin === null ? '' : `±${String(Math.round(margin))}`;
}

// Score points retain one decimal; the absolute margin rounds to the nearest whole point.
export function formatScore(score: CalculatedModelScore): string {
  const central = score.score.toFixed(1);
  const margin = formatMargin(score.uncertainty.margin);
  return `${central}${margin ? ` ${margin}` : ''}`;
}

src/engine/taskWorkload.ts:
export interface TaskUsage {
  input: number;
  answer: number;
  reasoning: number;
  cacheableInput: number | null;
}

export interface TaskRates {
  input: number;
  output: number;
  cacheHit: number | null;
  cacheWrite: number | null;
}

export interface TaskBillingFallback {
  prices: TaskRates;
  rate: { input: number; output: number; reasoning: number };
}

/** Reproduce AA's per-evaluation billing, without Intelligence Index weights. */
export function calculateTaskComponents(usage: TaskUsage, taskCount: number, rates: TaskRates,
  cacheHitRate: number | null, fallback?: TaskBillingFallback) {
  if (usage.cacheableInput !== null && cacheHitRate === null) return undefined;
  const cacheRead = usage.cacheableInput === null ? 0 : usage.cacheableInput * (cacheHitRate ?? 0);
  const tokens = {
    nonCacheInput: usage.cacheableInput === null ? usage.input : 0,
    cacheRead,
    cacheWrite: usage.cacheableInput === null ? 0 : usage.input - cacheRead,
    reasoning: usage.reasoning,
    answer: usage.answer
  };
  const price = (key: keyof typeof tokens, prices: TaskRates) => key === 'cacheRead'
    ? prices.cacheHit ?? prices.input : key === 'cacheWrite' ? prices.cacheWrite ?? prices.input
      : key === 'nonCacheInput' ? prices.input : prices.output;
  const costs = Object.fromEntries(Object.entries(tokens).map(([name, count]) => {
    const key = name as keyof typeof tokens;
    const share = fallback ? fallback.rate[key === 'reasoning' ? 'reasoning' : key === 'answer' ? 'output' : 'input'] : 0;
    const rate = price(key, rates) * (1 - share) + (fallback ? price(key, fallback.prices) * share : 0);
    return [key, count / taskCount / 1e6 * rate];
  })) as Record<keyof typeof tokens, number>;
  return { ...costs, R: usage.reasoning / taskCount, A: usage.answer / taskCount };
}

/** Performance coverage is deliberately independent of intelligence coverage. */
export function averageTaskBenchmarks(rows: { weight: number; value: number }[], minimum = 2) {
  if (rows.length < minimum) return undefined;
  return rows.reduce((sum, row) => sum + row.weight * row.value, 0)
    / rows.reduce((sum, row) => sum + row.weight, 0);
}

