import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { resolve, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as engine from './share/engine.js';
import { build } from 'bun';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const destination = resolve(process.argv[2] ?? resolve(root, 'exports/real-index'));
// A handoff must never replace someone else's existing files, including a previous handoff.
await mkdir(dirname(destination), { recursive: true });
await mkdir(destination);
const hashes = {};
const hash = value => createHash('sha256').update(value).digest('hex');
async function save(name, value) {
  const content = typeof value === 'string' ? value : JSON.stringify(value, null, 2) + '\n';
  await writeFile(resolve(destination, name), content, { flag: 'wx' });
  hashes[name] = hash(content);
}
const map = engine.buildMetricMap();
const selected = engine.selectBestObservations(engine.models, map, engine.observations);
const dataset = {
  schemaVersion: 1,
  models: engine.models,
  enabledModelIds: engine.enabledModels.map(model => model.id),
  disabledConfigurations: engine.disabledConfigurations,
  performanceEstimates: engine.performanceEstimates,
  taskPerformance: engine.taskPerformance,
  modelCatalog: engine.modelCatalog,
  releaseObservations: engine.releaseObservations,
  observations: engine.observations,
  bestObservations: [...selected.values()],
  calibrationReferences: engine.calibrationReferences,
  tokenPricing: engine.tokenPricing,
  reasoningProfiles: engine.reasoningProfiles,
};
const formula = {
  schemaVersion: 1,
  observationSelection: engine.OBSERVATION_SELECTION_POLICY,
  crossEffortPolicy: engine.CROSS_EFFORT_POLICY,
  performanceEstimation: engine.performanceEstimates.policy,
  tokenPriceBlend: engine.TOKEN_PRICE_BLEND,
  fallbackMarginPoints: engine.FALLBACK_MARGIN_POINTS,
  catalog: engine.catalog,
  metrics: [...map.values()],
  calibrations: engine.calibrations,
};
const score = (metricId, models = engine.models) => engine.calculateIndexScores(metricId, models, map, engine.observations, engine.calibrations, engine.models)
  .map(({ model, ...result }) => ({ modelId: model.id, ...result }));
const composites = [...map.values()].filter(metric => metric.kind === 'composite');
const compositeScores = composites.map(metric => ({ metricId: metric.id, fallbackOnly: metric.fallbackOnly ?? false, scores: score(metric.id, engine.enabledModels) }));
const resolvedBenchmarks = [...map.values()].filter(metric => metric.kind === 'raw').flatMap(metric =>
  score(metric.id).map(result => ({ modelId: result.modelId, metricId: metric.id, ...result.leafBreakdown[0] })));
const calibrationEvidence = engine.generateFallbackCalibrations(engine.models, map, engine.observations,
  engine.catalog.manualCalibrations ?? [], engine.calibrationReferences);
await save('dataset.json', dataset);
await save('formulas.json', formula);
await save('composite-scores.json', compositeScores);
await save('resolved-benchmarks.json', resolvedBenchmarks);
await save('calibration-evidence.json', calibrationEvidence);
// Preserve hashed bytes when this package is committed and checked out on Windows.
await save('.gitattributes', '* -text\n');

const built = await build({ entrypoints: [resolve(root, 'scripts/share/engine.js')], target: 'browser', format: 'esm', minify: false });
if (!built.success) throw new Error(built.logs.join('\n'));
await save('engine.mjs', await built.outputs[0].text());
for (const name of ['README.md', 'priors.mjs', 'verify.mjs']) {
  await save(name, await readFile(resolve(root, 'scripts/share', name), 'utf8'));
}
await save('methodology.md', await readFile(resolve(root, 'reports/fallback-scoring-2026-09-05.md'), 'utf8'));
await save('arc-overlap-calibration-2026-09-05.md', await readFile(resolve(root, 'reports/arc-overlap-calibration-2026-09-05.md'), 'utf8'));
// Preserve readable original source without adding TypeScript files to the recipient's compilation.
const sources = {};
for (const folder of ['src/data', 'src/engine', 'src/types', 'scripts/share']) {
  for (const file of await readdir(resolve(root, folder))) {
    if (!/\.(ts|js|json|mjs|md)$/.test(file) || /\.test\.|testUtils|runTests/.test(file)) continue;
    const name = `${folder}/${file}`;
    sources[name] = await readFile(resolve(root, name), 'utf8');
  }
}
sources['scripts/exportDataset.js'] = await readFile(resolve(root, 'scripts/exportDataset.js'), 'utf8');
for (const name of ['scripts/generatePerformanceEstimates.js', 'scripts/generateTaskPerformance.js',
  'reports/task-benchmark-inputs-2026-09-07.json', 'reports/performance-component-inputs-2026-09-06.json',
  'reports/aa-performance-gaps-2026-09-06.json',
  'reports/task-basket-2026-09-07.md', 'reports/performance-component-design-2026-09-06.md']) {
  sources[name] = await readFile(resolve(root, name), 'utf8');
}
await save('source-files.json', sources);
await save('manifest.json', {
  schemaVersion: 1, generatedAt: new Date().toISOString(),
  sourceCommit: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
  workingTreeChanges: execFileSync('git', ['status', '--porcelain', '--untracked-files=normal'], { cwd: root, encoding: 'utf8' }).trim().split('\n').filter(Boolean),
  counts: { configurations: dataset.models.length, enabledConfigurations: dataset.enabledModelIds.length, releaseObservations: dataset.releaseObservations.length,
    assignedObservations: dataset.observations.length, bestObservations: dataset.bestObservations.length,
    referenceModels: dataset.calibrationReferences.models.length, referenceObservations: dataset.calibrationReferences.observations.length,
    rawMetrics: [...map.values()].filter(metric => metric.kind === 'raw').length,
    compositeMetrics: composites.length, resolvedBenchmarks: resolvedBenchmarks.length,
    compositeScores: compositeScores.reduce((sum, item) => sum + item.scores.length, 0) },
  files: { ...hashes },
});
console.log(`Exported ${relative(root, destination)}. Verify with: node "${resolve(destination, 'verify.mjs')}"`);

scripts/generatePerformanceEstimates.js:
import { writeFile } from 'node:fs/promises';
import inputs from '../reports/performance-component-inputs-2026-09-06.json';
import gaps from '../reports/aa-performance-gaps-2026-09-06.json';
import { initialModels } from '../src/data/models.ts';
import { metricObservations } from '../src/data/observations.ts';
import { buildMetricMap } from '../src/data/metrics.ts';
import { selectBestObservations } from '../src/engine/observations.ts';

// Frozen, coherent AA snapshot. Estimates never enter the observation/calibration pool.
const date = '2026-09-06';
const fields = ['R', 'A', 'nonCacheInput', 'cacheRead', 'cacheWrite', 'reasoning', 'answer'];
const costs = fields.slice(2);
// Output costs and task time share the same estimated token counts.
const fitKey = key => key === 'reasoning' ? 'R' : key === 'answer' ? 'A' : key;
const rows = inputs.rows.filter(row => row.release !== 'gpt-6-astra');
const value = (row, key) => row[key] ?? row.costComponents[key];
const mean = values => values.reduce((sum, v) => sum + v, 0) / values.length;
const metrics = buildMetricMap();
const selected = selectBestObservations(initialModels, metrics, metricObservations);
// Select snapshot measurements separately so timing and components stay in the same harness/date.
const measurements = rows.flatMap(row => Object.entries({ 'output-speed': row.S,
  'time-to-first-answer-token': row.L, 'time-per-task': row.T, 'cost-per-task': row.C })
  .map(([metricId, numeric]) => ({ modelId: row.slug, metricId, value: numeric,
    sourceUrl: row.sourceUrl, observationDate: date, reasoningBudget: row.effort ?? 'Not published' })));
const snapshot = selectBestObservations(rows.map(row => ({ id: row.slug, isReasoningModel: true })), metrics, measurements);
const read = (row, metricId) => snapshot.get(`${row.slug}:${metricId}`).value;
const allPairs = rows.flatMap(top => rows.filter(low => top.release === low.release
  && top.level && low.level && top.level > low.level).map(low => ({ top, low,
    transition: `${top.effort}->${low.effort}`, x: low.X / top.X })));
const topPairs = allPairs.filter(pair => !rows.some(row => row.release === pair.top.release && row.level > pair.top.level));
const ratio = (pairs, key) => mean(pairs.map(p => value(p.low, key))) / mean(pairs.map(p => value(p.top, key)));
const timingRatio = (pairs, key) => mean(pairs.map(p => p.low[key])) / mean(pairs.map(p => p.top[key]));
function exponent(pairs, key) {
  const usable = pairs.filter(p => value(p.top, key) > 0 && value(p.low, key) > 0);
  const count = release => usable.filter(p => p.top.release === release).length;
  return usable.reduce((sum, p) => sum + Math.log(p.x) * Math.log(value(p.low, key) / value(p.top, key)) / count(p.top.release), 0)
    / usable.reduce((sum, p) => sum + Math.log(p.x) ** 2 / count(p.top.release), 0);
}
const aliases = { 'deepseek-v4-flash-0731': 'deepseek-v4-flash', 'deepseek-v4-pro-max': 'deepseek-v4-pro',
  'glm-5-3-max': 'glm-5-3', 'kimi-k3-max': 'kimi-k3', 'claude-fable-5-1-max': 'claude-fable-5-1',
  'grok-4-6-high': 'grok-4-6', 'gemini-3-8-flash-high': 'gemini-3-8-flash', 'gpt-5-6-luna-max': 'gpt-5-6-luna' };
const configurations = [];
for (const model of initialModels) {
  const config = model.reasoningConfiguration;
  if (!config || !['middle', 'lowest'].includes(config.tier)) continue;
  const topModel = initialModels.find(m => m.reasoningConfiguration?.releaseId === config.releaseId && m.reasoningConfiguration.tier === 'top');
  const topEffort = topModel?.reasoningConfiguration.effort;
  const top = rows.find(row => row.release === (aliases[config.releaseId] ?? config.releaseId)
    && (row.effort === topEffort || !row.effort));
  if (!top) continue;
  const peers = allPairs.filter(p => p.transition === `${topEffort}->${config.effort}` && p.top.release !== top.release);
  if (!peers.length) continue;
  const target = gaps.gaps.find(gap => gap.modelId === model.id)?.matchingRows[0];
  const speed = target?.values['output-speed'];
  const latency = target?.values['time-to-first-answer-token'];
  const lowerSpeed = speed ?? read(top, 'output-speed') * timingRatio(peers, 'S');
  const lowerLatency = latency ?? read(top, 'time-to-first-answer-token') * timingRatio(peers, 'L');
  const components = fields.map(key => {
    const peerFactor = ratio(peers, fitKey(key));
    const topValue = value(top, key);
    return { key, topValue, peerFactor, factor: peerFactor, value: topValue * peerFactor };
  });
  const estimated = key => components.find(part => part.key === key).value;
  const values = {
    'time-per-task': read(top, 'time-per-task') * (estimated('R') + estimated('A')) / (top.R + top.A) * read(top, 'output-speed') / lowerSpeed,
    'cost-per-task': costs.reduce((sum, key) => sum + estimated(key), 0)
  };
  if (!selected.has(`${model.id}:output-speed`)) values['output-speed'] = lowerSpeed;
  if (!selected.has(`${model.id}:time-to-first-answer-token`)) values['time-to-first-answer-token'] = lowerLatency;
  configurations.push({ modelId: model.id, releaseId: config.releaseId, effort: config.effort,
    topEffort, topEffortAssumed: !top.effort, topSourceUrl: top.sourceUrl, targetSourceUrl: target?.sourceUrl ?? null,
    route: 'peer', date, values, components,
    topTime: read(top, 'time-per-task'), topSpeed: read(top, 'output-speed'), topLatency: read(top, 'time-to-first-answer-token'),
    lowerSpeed, lowerLatency, speedEstimated: !speed, latencyEstimated: !latency,
    speedFactor: timingRatio(peers, 'S'), latencyFactor: timingRatio(peers, 'L'),
    donors: peers.map(p => ({ releaseId: p.top.release, topSourceUrl: p.top.sourceUrl, lowerSourceUrl: p.low.sourceUrl })) });
}
// Leave each entire release out. Validate all native transitions used by the shipped estimates,
