scripts/generateTaskPerformance.js:
import { readFile, writeFile } from 'node:fs/promises';
import inputs from '../reports/task-benchmark-inputs-2026-09-07.json';
import timingInputs from '../reports/performance-component-inputs-2026-09-06.json';
import { metricObservations } from '../src/data/observations.ts';
import { buildMetricMap } from '../src/data/metrics.ts';
import { selectBestObservations } from '../src/engine/observations.ts';
import { initialModels } from '../src/data/models.ts';
import { calculateTaskComponents, averageTaskBenchmarks } from '../src/engine/taskWorkload.ts';

const fields = ['R', 'A', 'nonCacheInput', 'cacheRead', 'cacheWrite', 'reasoning', 'answer'];
const costs = fields.slice(2);
const mean = values => values.reduce((sum, value) => sum + value, 0) / values.length;
const legacy = JSON.parse(await readFile('src/data/performanceEstimates.json', 'utf8'));
const legacyByModel = new Map(legacy.configurations.map(row => [row.modelId, row]));
const releaseId = id => inputs.releaseAliases[id] ?? id;
const match = model => {
  const config = model.reasoningConfiguration;
  if (!config) return undefined;
  return inputs.rows.find(row => row.release === releaseId(config.releaseId)
    && (row.effort === config.effort || (row.effort === null && ['top', 'single'].includes(config.tier))));
};
const components = (row, benchmark) => {
  const usage = row.tokens[benchmark.key];
  if (!usage || row.rates.input === null || row.rates.output === null) return undefined;
  const billing = row.fallbackBilling;
  return calculateTaskComponents(usage, benchmark.taskCount, row.rates, row.cacheHitRate,
    billing && billing.rateByBenchmark[benchmark.key]
      ? { prices: billing.prices, rate: billing.rateByBenchmark[benchmark.key] } : undefined);
};
const fitBenchmark = (top, effort, topEffort, benchmark) => {
  const anchor = components(top, benchmark);
  if (!anchor) return undefined;
  let parts;
  const fits = [];
  const donors = new Map();
      const pairs = inputs.rows.filter(row => row.effort === topEffort
        && row.release !== top.release && row.release !== 'gpt-6-astra').flatMap(peerTop => {
        const low = inputs.rows.find(row => row.release === peerTop.release && row.effort === effort);
        const a = components(peerTop, benchmark);
        const b = low && components(low, benchmark);
        return a && b ? [{ top: peerTop, low, a, b }] : [];
      });
      if (pairs.length) {
        parts = {};
        for (const key of fields) {
          const fitKey = key === 'reasoning' ? 'R' : key === 'answer' ? 'A' : key;
          const denominator = mean(pairs.map(pair => pair.a[fitKey]));
          const factor = denominator > 0 ? mean(pairs.map(pair => pair.b[fitKey])) / denominator
            : anchor[key] === 0 ? 1 : undefined;
          if (factor === undefined) { parts = undefined; break; }
          parts[key] = anchor[key] * factor;
          fits.push({ key, topValue: anchor[key], factor, value: parts[key] });
        }
        if (parts) for (const pair of pairs) donors.set(pair.top.release, {
          releaseId: pair.top.release, topSourceUrl: pair.top.sourceUrl, lowerSourceUrl: pair.low.sourceUrl
        });
      }
  return parts ? { parts, fits, donors: [...donors.values()] } : undefined;
};
const selected = selectBestObservations(initialModels, buildMetricMap(), metricObservations);
const observations = [];
const configurations = [];
const estimates = [];
for (const model of initialModels) {
  const config = model.reasoningConfiguration;
  if (!config) continue;
  const direct = match(model);
  const topModel = initialModels.find(row => row.reasoningConfiguration?.releaseId === config.releaseId
    && ['top', 'single'].includes(row.reasoningConfiguration.tier));
  const top = topModel && match(topModel);
  const old = legacyByModel.get(model.id);
  const topEffort = top?.effort ?? topModel?.reasoningConfiguration.effort;
  const speedPairs = inputs.rows.filter(row => row.effort === topEffort && row.release !== top?.release
    && row.release !== 'gpt-6-astra').flatMap(a => {
    const b = inputs.rows.find(row => row.release === a.release && row.effort === config.effort);
    return a.outputSpeed > 0 && b?.outputSpeed > 0 ? [{ a, b }] : [];
  });
  const speedFactor = speedPairs.length ? mean(speedPairs.map(p => p.b.outputSpeed)) / mean(speedPairs.map(p => p.a.outputSpeed)) : undefined;
  const speed = direct?.outputSpeed ?? old?.lowerSpeed ?? (top && speedFactor ? top.outputSpeed * speedFactor : undefined);
  const latencyPairs = timingInputs.rows.filter(row => row.effort === topEffort && row.release !== top?.release
    && row.release !== 'gpt-6-astra').flatMap(a => {
    const b = timingInputs.rows.find(row => row.release === a.release && row.effort === config.effort);
    return b ? [{ a, b }] : [];
  });
  const latencyFactor = latencyPairs.length ? mean(latencyPairs.map(p => p.b.L)) / mean(latencyPairs.map(p => p.a.L)) : undefined;
  const topLatency = old?.topLatency ?? selected.get(`${topModel?.id}:time-to-first-answer-token`)?.value;
  const lowerLatency = old?.lowerLatency ?? (topLatency !== undefined && latencyFactor !== undefined ? topLatency * latencyFactor : undefined);
  const benchmarks = [];
  const donors = new Map();
  for (const benchmark of inputs.benchmarks) {
    const measured = direct && components(direct, benchmark);
    const anchor = top && components(top, benchmark);
    let parts = measured;
    const fits = [];
    if (!parts && anchor && !['top', 'single'].includes(config.tier)) {
      const fit = fitBenchmark(top, config.effort, topEffort, benchmark);
      parts = fit?.parts;
      if (fit) {
        fits.push(...fit.fits);
        for (const donor of fit.donors) donors.set(donor.releaseId, donor);
      }
    }
    if (!parts) continue;
    benchmarks.push({ ...benchmark, sourceUrl: `https://artificialanalysis.ai/evaluations/${benchmark.slug}`,
      modelSourceUrl: direct?.sourceUrl ?? top?.sourceUrl,
      state: measured ? 'measured' : 'estimated', components: parts, fits,
      values: { 'cost-per-task': costs.reduce((sum, key) => sum + parts[key], 0),
        ...(speed > 0 ? { 'time-per-task': (parts.R + parts.A) / speed } : {}),
        'reasoning-tokens-per-task': parts.R, 'answer-tokens-per-task': parts.A,
        'output-tokens-per-task': parts.R + parts.A } });
  }
  const values = {};
  const metricIds = ['cost-per-task', 'time-per-task', 'reasoning-tokens-per-task', 'answer-tokens-per-task', 'output-tokens-per-task'];
  for (const metricId of metricIds) {
    const value = averageTaskBenchmarks(benchmarks.filter(row => row.values[metricId] !== undefined)
      .map(row => ({ weight: row.weight, value: row.values[metricId] })), inputs.minimumBenchmarks);
    if (value !== undefined) values[metricId] = value;
  }
  const notes = `Fixed task basket v1: ${benchmarks.length}/${inputs.benchmarks.length} benchmarks; minimum ${inputs.minimumBenchmarks}. `
    + 'Available benchmark weights are renormalized for performance only. '
    + benchmarks.map(row => `${row.name} ${row.version}: ${row.state}; $${row.values['cost-per-task'].toFixed(6)}, `
      + `${row.values['time-per-task']?.toFixed(3) ?? 'unavailable'} s; ${row.sourceUrl}`).join(' | ')
    + ' Time is output decode time, excluding first-token latency and tool overhead.';
  configurations.push({ modelId: model.id, releaseId: config.releaseId, effort: config.effort,
    sourceEffort: direct?.effort ?? null, date: inputs.date, outputSpeed: speed ?? null,
    benchmarkCount: benchmarks.length, values, benchmarks, notes });
  if (direct && benchmarks.every(row => row.state === 'measured')) {
    for (const metricId of ['cost-per-task', 'time-per-task', 'output-tokens-per-task']) {
      if (values[metricId] === undefined) continue;
      observations.push({ modelId: model.id, metricId, value: values[metricId], observationDate: inputs.date,
        sourceUrl: inputs.sourceUrl, configurationEffort: direct.effort,
        reasoningBudget: direct.effort ?? 'Not published', reasoningMode: 'reasoning',
        scaffoldOrHarness: 'Fixed task basket v1; AA per-evaluation canonical usage and billing', notes });
    }
  } else if (top && benchmarks.length >= inputs.minimumBenchmarks && speed > 0 && lowerLatency !== undefined) {
    const parts = fields.map(key => {
      const topValue = mean(benchmarks.map(benchmark => components(top, benchmark)[key]));
      const value = mean(benchmarks.map(benchmark => benchmark.components[key]));
      const factor = topValue > 0 ? value / topValue : 1;
      return { key, topValue, peerFactor: factor, factor, value };
    });
    const topTokens = parts.filter(part => ['R', 'A'].includes(part.key)).reduce((sum, part) => sum + part.topValue, 0);
    estimates.push({ modelId: model.id, releaseId: config.releaseId, effort: config.effort, topEffort,
      topLatency, lowerLatency, speedFactor: old?.speedFactor ?? speedFactor,
      latencyFactor: old?.latencyFactor ?? latencyFactor,
      speedEstimated: old?.speedEstimated ?? !direct, latencyEstimated: old?.latencyEstimated ?? true,
      targetSourceUrl: old?.targetSourceUrl ?? direct?.sourceUrl ?? null,
      date: inputs.date, topSourceUrl: top.sourceUrl, route: 'peer',
      topEffortAssumed: top.effort === null, components: parts,
      topTime: topTokens / top.outputSpeed, topSpeed: top.outputSpeed, lowerSpeed: speed,
      values: { ...Object.fromEntries(Object.entries(values).filter(([key]) => ['cost-per-task', 'time-per-task', 'output-tokens-per-task'].includes(key))),
        ...(!selected.has(`${model.id}:output-speed`) ? { 'output-speed': speed } : {}),
        ...(!selected.has(`${model.id}:time-to-first-answer-token`) ? { 'time-to-first-answer-token': lowerLatency } : {}) },
      donors: [...donors.values()], taskBenchmarks: benchmarks, notes });
  }
}
// Keep legacy speed/latency estimates. Rolling-index task estimates must never fill a fixed-basket gap.
const merged = new Map(legacy.configurations.map(row => [row.modelId, { ...row,
  values: Object.fromEntries(Object.entries(row.values).filter(([key]) => !['cost-per-task', 'time-per-task', 'output-tokens-per-task'].includes(key))) }]));
for (const estimate of estimates) merged.set(estimate.modelId, { ...estimate,
  values: { ...merged.get(estimate.modelId)?.values, ...estimate.values } });
const frozen = { policy: 'fixed-task-basket-v1-peer-components', date: inputs.date,
  excludedReferences: ['gpt-6-astra'], configurations: [...merged.values()].filter(row => Object.keys(row.values).length) };
await writeFile('src/data/taskPerformance.json', JSON.stringify({ version: '1.0', date: inputs.date,
  minimumBenchmarks: inputs.minimumBenchmarks, benchmarks: inputs.benchmarks, configurations, observations }, null, 2) + '\n');
await writeFile('src/data/performanceEstimates.json', JSON.stringify(frozen, null, 2) + '\n');
console.log(JSON.stringify({ measuredConfigurations: new Set(observations.map(row => row.modelId)).size, estimatedConfigurations: estimates.length,
  belowMinimum: configurations.filter(row => row.benchmarkCount < inputs.minimumBenchmarks).map(row => row.modelId) }, null, 2));

// Hold out the entire target release; validation never trains on its other native settings.
const transitions = new Set(estimates.map(row => `${row.topEffort}->${row.effort}`));
const validation = inputs.rows.filter(row => row.effort && row.release !== 'gpt-6-astra').flatMap(top =>
  inputs.rows.filter(low => low.release === top.release && transitions.has(`${top.effort}->${low.effort}`)).flatMap(low => {
    const rows = inputs.benchmarks.flatMap(benchmark => {
      const actual = components(low, benchmark);
      const fit = fitBenchmark(top, low.effort, top.effort, benchmark);
      if (!actual || !fit || !(low.outputSpeed > 0)) return [];
      return [{ benchmark: benchmark.key,
        actualCost: costs.reduce((sum, key) => sum + actual[key], 0),
        predictedCost: costs.reduce((sum, key) => sum + fit.parts[key], 0),
        actualTime: (actual.R + actual.A) / low.outputSpeed,
        predictedTime: (fit.parts.R + fit.parts.A) / low.outputSpeed }];
    });
    if (rows.length < inputs.minimumBenchmarks) return [];
    return [{ release: top.release, transition: `${top.effort}->${low.effort}`, benchmarks: rows.length,
      actualCost: mean(rows.map(row => row.actualCost)), predictedCost: mean(rows.map(row => row.predictedCost)),
      actualTime: mean(rows.map(row => row.actualTime)), predictedTime: mean(rows.map(row => row.predictedTime)) }];
  }));
const median = values => { const sorted = [...values].sort((a, b) => a - b); return sorted.length
  ? (sorted[Math.floor((sorted.length - 1) / 2)] + sorted[Math.ceil((sorted.length - 1) / 2)]) / 2 : null; };
await writeFile('reports/task-performance-validation-2026-09-07.json', JSON.stringify({ date: inputs.date,
  note: 'Fixed basket, release-held-out peer components. Time validation supplies measured lower speed; it does not validate missing-speed estimates.',
  pairs: validation.length, medianAbsolutePercentError: Object.fromEntries(['Cost', 'Time'].map(key => [key,
    median(validation.map(row => Math.abs(row[`predicted${key}`] / row[`actual${key}`] - 1) * 100))])), validation }, null, 2) + '\n');

